function doAttack(){if(!started||ended||attackTimer>0)return;attackTimer=.58;slash.visible=true;slash.position.set(hero.position.x,1.15,hero.position.z-1.0);slash.rotation.z=-hero.rotation.y;for(const e of [...enemies]){const d=e.position.distanceTo(hero.position);if(d<3.35){e.userData.hp--;e.userData.hit=.2;burst(e.position.clone().add(new THREE.Vector3(0,1,0)),'#afeaff',6);if(e.userData.hp<=0){burst(e.position.clone().add(new THREE.Vector3(0,1,0)),'#de9b6b',16);scene.remove(e);enemies.splice(enemies.indexOf(e),1);kills++;spawnTimer=1.6;updateHUD()}}}}
function doDash(){if(!started||ended||dashTimer>0)return;dashTimer=.9;damageTimer=.35;hero.userData.dash=.22;}
let joy={x:0,y:0};const stick=document.querySelector('#stick'),nub=document.querySelector('#nub');let stickPointer=null;function setJoy(e){const r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=39,m=Math.min(len,max);joy.x=len?dx/len*m/max:0;joy.y=len?dy/len*m/max:0;nub.style.transform=`translate(${joy.x*m}px,${joy.y*m}px)`}stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);setJoy(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)setJoy(e)});const resetJoy=()=>{stickPointer=null;joy={x:0,y:0};nub.style.transform=''};stick.addEventListener('pointerup',resetJoy);stick.addEventListener('pointercancel',resetJoy);
