for(const p of pickups){if(p.userData.taken)continue;p.rotation.y+=dt*.65;p.position.y=Math.sin(time*2+p.position.x)*.18;if(p.position.distanceTo(hero.position)<1.65){p.userData.taken=true;scene.remove(p);souls++;burst(new THREE.Vector3(p.position.x,1,p.position.z),'#a6efff',22);notify('SOUL-SHARD RECOVERED');updateHUD()}}
for(const e of [...enemies]){e.userData.phase+=dt*3;e.position.y=Math.abs(Math.sin(e.userData.phase))*.12;e.rotation.y+=dt*.45;const dx=hero.position.x-e.position.x,dz=hero.position.z-e.position.z,d=Math.hypot(dx,dz);if(d>1.5){e.position.x+=dx/d*e.userData.speed*dt;e.position.z+=dz/d*e.userData.speed*dt;e.rotation.y=Math.atan2(dx,dz)}else if(damageTimer<=0){hp=Math.max(0,hp-12);damageTimer=.85;hero.material&& (hero.material.opacity=.5);updateHUD();if(hp<=0)finish(false)}if(e.userData.hit>0){e.userData.hit-=dt;e.position.x-=dx/(d||1)*dt*3}}
if(enemies.length<5&&kills<8&&spawnTimer===0)spawnEnemy();if(souls===3&&kills>=8&&Math.hypot(hero.position.x,hero.position.z+18)<4.4)finish(true);
const target=new THREE.Vector3(hero.position.x,1.15,hero.position.z+6.8);camera.position.lerp(new THREE.Vector3(hero.position.x,5.9,hero.position.z+10.5),1-Math.pow(.001,dt));camera.lookAt(target);
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.v.y-=4*dt;p.mesh.material.opacity=Math.max(0,p.life);if(p.life<=0){scene.remove(p.mesh);particles.splice(i,1)}}}
function render(){renderer.render(scene,camera)}let prev=performance.now();function loop(now){requestAnimationFrame(loop);const dt=Math.min((now-prev)/1000,.04);prev=now;update(dt);render()}requestAnimationFrame(loop);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});updateHUD();
</script>
